const D = { energy: .55, scale: 1, density: .55, speed: 1, depth: .6, dust: .5, hue: 34, x: .5, y: .3, style: 'overburden', act: 'shift', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 34;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];

// ---------------- styles ----------------
const STY = {
  // grey limestone under an overcast sky — industrial, scarred, indifferent
  overburden: { skyT:[206,14,44], skyL:[200,7,66], berm:[38,7,44], batter:[34,9,26], lip:[36,10,58],
                lake:[176,32,44], dust:[38,6,72], haze:[200,8,62], cloud:0, pts:0, line:0, grain:26 },
  // iron ore — red oxide, warm, the whole pit stained
  ironstone:  { skyT:[24,26,42], skyL:[28,30,64], berm:[18,44,42], batter:[12,52,24], lip:[26,40,58],
                lake:[36,60,34], dust:[18,38,66], haze:[24,26,56], cloud:0, pts:0, line:0, grain:34 },
  // sodium floods on the night shift — dark key, warm pools, the pit is a void
  nightwork:  { skyT:[234,46,14], skyL:[224,30,26], berm:[36,28,32], batter:[228,30,16], lip:[40,44,44],
                lake:[196,34,16], dust:[38,34,40], haze:[220,28,20], cloud:0, pts:0, line:0, grain:18 },
  // ABSTRACTED: LiDAR survey — the pit exists only as a point cloud on an elevation ramp
  lidar:      { skyT:[232,34,20], skyL:[230,28,27], berm:[150,70,70], batter:[220,70,44], lip:[60,80,92],
                lake:[280,60,60], dust:[180,20,40], haze:[230,30,12], cloud:0, pts:1, line:0, grain:0 },
  // ABSTRACTED: mine plan — drafting ground, bench crests as line, hachures down the batters
  mineplan:   { skyT:[216,56,19], skyL:[214,48,26], berm:[214,44,22], batter:[216,50,16], lip:[186,46,92],
                lake:[188,52,70], dust:[196,30,30], haze:[210,40,18], cloud:0, pts:0, line:1, grain:4 }
};
const st = STY[P.style] || STY.overburden;

const en = Math.max(0, Math.min(1, P.energy));
const du = Math.max(0, Math.min(1, P.dust));
const rimY = height * P.y;                        // the far rim against the sky
const cx = width * P.x;
const NB = Math.max(5, Math.round((7 + P.density * 12) / Math.max(.5, P.scale * .75)));   // bench count
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.depth.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

// bench k: an ellipse that shrinks and sinks as it descends — the annulus left visible at
// the TOP of each ring is the far batter face, which is exactly where a real pit reads.
const RW0 = width * .82 * (.7 + P.scale * .4);
const RH0 = u * .30 * (.7 + P.scale * .4);
const cy0 = rimY + RH0 * .82;
const sink = u * (.10 + .34 * P.depth);
const ringW = k => RW0 * (1 - .90 * (k / NB));
const ringH = k => RH0 * (1 - .90 * (k / NB));
const ringY = k => cy0 + sink * Math.pow(k / NB, .78);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.pit.remove(); S.hz0.remove(); S.hz1.remove(); }
  S.sky = mk(W, H); S.pit = mk(W, H); S.hz0 = mk(W, H); S.hz1 = mk(W, H);

  const g = S.sky; g.noStroke();
  const cT = sh(st.skyT), cL = sh(st.skyL);
  for (let yy = 0; yy < H; yy++) { const c = L3(cT, cL, Math.pow(Math.min(1, yy / Math.max(1, rimY + u * .1)), .85)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }

  const q = S.pit; q.noStroke();
  const bermC = sh(st.berm), batC = sh(st.batter), lipC = sh(st.lip), hazeC = sh(st.haze), lakeC = sh(st.lake);

  // --- spoil ground outside the rim: the world the pit was cut out of ---
  if (!st.pts) {
    const og = L3(bermC, hazeC, .18);
    q.fill(og[0], og[1] * .8, og[2] * .82); q.rect(0, rimY - u * .01, W, H - rimY + u * .01);
    q.beginShape(); q.vertex(-20, H);
    for (let xx = -20; xx <= W + 20; xx += 24) q.vertex(xx, rimY - Math.abs(Math.sin(xx * .0037 + fr(2) * 6)) * u * .022 - Math.sin(xx * .011) * u * .006);
    q.vertex(W + 20, H); q.endShape(q.CLOSE);
  }

  // --- the benches, rim inward. Each smaller ring overpaints, leaving the far batter proud ---
  S.wpts = [];
  for (let k = 0; k < NB; k++) {
    const f = k / NB;                              // 0 rim -> 1 floor
    const rw = ringW(k), rh = ringH(k), ry = ringY(k);
    const haze = (1 - Math.pow(f, .8)) * (.14 + .34 * du);       // the far/upper rings sit back in the dust
    const vj = (fr(k * 17 + 3) - .5) * 9;
    const bm = L3([bermC[0], bermC[1], Math.max(3, bermC[2] * (.62 + .55 * f) + vj)], hazeC, haze);
    const bt = L3([batC[0], batC[1], Math.max(2, batC[2] * (.6 + .6 * f))], hazeC, haze);

    if (st.pts) {
      // LiDAR: no surfaces at all, only returns — elevation ramp along the scan rings
      const ramp = L3(sh(st.batter), sh(st.berm), f);
      for (let i = 0; i < 150; i++) {
        const a = (i / 150) * Math.PI * 2 + fr(k * 5 + i) * .04;
        const jr = 1 + (fr(k * 7 + i * 3) - .5) * .02;
        q.fill(ramp[0], ramp[1], Math.min(99, ramp[2] + (fr(i + k) - .5) * 18), 60 + fr(i * 2 + k) * 34);
        q.rect(cx + Math.cos(a) * rw * .5 * jr, ry + Math.sin(a) * rh * .5 * jr, 1.6, 1.6);
      }
      continue;
    }
    if (st.line) {
      // mine plan: the bench crest as a drafted line + hachures down the batter
      q.noFill(); q.strokeWeight(Math.max(.6, u * .0014 * (.4 + f)));
      q.stroke(lipC[0], lipC[1], lipC[2], 62);
      q.ellipse(cx, ry, rw, rh);
      q.strokeWeight(Math.max(.4, u * .0008));
      for (let i = 0; i < 64; i++) {
        const a = (i / 64) * Math.PI * 2;
        const rw2 = ringW(k + 1), rh2 = ringH(k + 1), ry2 = ringY(k + 1);
        q.stroke(lipC[0], lipC[1] * .8, lipC[2] * .7, 26);
        q.line(cx + Math.cos(a) * rw * .5, ry + Math.sin(a) * rh * .5, cx + Math.cos(a) * rw2 * .5, ry2 + Math.sin(a) * rh2 * .5);
      }
      q.noStroke();
      continue;
    }

    // the batter face (fills the whole ring; the next ring will overpaint the berm on top of it)
    q.fill(bt[0], bt[1], bt[2]); q.ellipse(cx, ry, rw, rh);
    // drill-and-blast striations down the batter — texture, never a flat fill
    const nst = Math.floor(50 * (.4 + f * .8));
    q.strokeWeight(Math.max(.5, u * .0011 * (.3 + f)));
    for (let i = 0; i < nst; i++) {
      const a = (i / nst) * Math.PI * 2 + fr(k * 3 + i) * .05;
      const sy2 = Math.sin(a);
      if (sy2 > .25) continue;                     // only the far half of the ring is visible
      const v2 = (fr(k * 11 + i * 5) - .5) * 22;
      q.stroke(bt[0], bt[1] * (.8 + fr(i) * .4), Math.max(2, bt[2] + v2), 34 + fr(i * 2) * 30);
      q.line(cx + Math.cos(a) * rw * .5, ry + sy2 * rh * .5,
             cx + Math.cos(a) * ringW(k + .92) * .5, ringY(k + .92) + sy2 * ringH(k + .92) * .5);
    }
    q.noStroke();
    // the berm: the flat working shelf, catching the sky
    const rwB = ringW(k + .34), rhB = ringH(k + .34), ryB = ringY(k + .34);
    q.fill(bm[0], bm[1], bm[2]); q.ellipse(cx, ryB, rwB, rhB);
    // the crest lip highlight — the one hard edge per bench
    q.noFill(); q.strokeWeight(Math.max(.5, u * .0012 * (.35 + f * 1.3)));
    const lp = L3(lipC, hazeC, haze);
    q.stroke(lp[0], lp[1] * .7, lp[2], 40 + 26 * f);
    q.ellipse(cx, ryB, rwB, rhB);
    q.noStroke();
    // scree fans spilling off the crest
    for (let i = 0; i < 5; i++) {
      const a = -Math.PI * (.15 + fr(k * 9 + i) * .7);
      q.fill(bm[0], bm[1] * 1.1, Math.max(2, bm[2] * .8), 30);
      q.triangle(cx + Math.cos(a) * rwB * .5, ryB + Math.sin(a) * rhB * .5,
                 cx + Math.cos(a) * rw * .5 - u * .012, ry + Math.sin(a) * rh * .5,
                 cx + Math.cos(a) * rw * .5 + u * .012, ry + Math.sin(a) * rh * .5);
    }
    S.wpts.push({ k: k, f: f });
  }

  // --- the pit lake: acid drainage standing in the floor ---
  const lw = ringW(NB - .2), lh = ringH(NB - .2), ly = ringY(NB - .2);
  if (!st.pts) {
    if (st.line) { q.noFill(); q.strokeWeight(Math.max(.7, u * .0016)); q.stroke(lakeC[0], lakeC[1], lakeC[2], 70); q.ellipse(cx, ly, lw, lh); q.noStroke(); }
    else { q.fill(lakeC[0], lakeC[1], lakeC[2] * .7, 96); q.ellipse(cx, ly, lw, lh);
           q.fill(lakeC[0], lakeC[1] * .8, lakeC[2], 60); q.ellipse(cx, ly, lw * .7, lh * .7); }
  }
  S.lake = { x: cx, y: ly, w: lw, h: lh };

  // --- two tileable dust hazes that hang in the pit ---
  const dC = sh(st.dust);
  for (const [gg, n, yc, spr, thk, alp] of [[S.hz0, 10, cy0 + sink * .3, u * .30, u * .06, 17], [S.hz1, 7, cy0 + sink * .7, u * .18, u * .035, 22]]) {
    gg.noStroke();
    for (let i = 0; i < n; i++) {
      const bx = fr(i * 5 + 81) * W, by = yc + (fr(i * 5 + 82) - .5) * spr;
      const bw = u * (.25 + fr(i * 5 + 83) * .7), bhh = thk * (.5 + fr(i * 5 + 84));
      for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
        gg.fill(dC[0], dC[1] * (1 - kk * .1), Math.min(99, dC[2] + kk * 2), alp * (1 - kk * .2));
        gg.ellipse(bx + rep * W, by + kk * bhh * .14, bw * (1 - kk * .12), bhh * (1 - kk * .08));
      }
    }
  }
  S.key = key;
}

// ---------------- act: what the pit is doing over minutes ----------------
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { shift: { d: .8 + sec * .05, l: .9 }, blast: { d: .4 + sec * .17, l: 1 }, abandoned: { d: .25, l: .7 + sec * .03 } };
const act = ACT[P.act] || ACT.shift;
const dustAmt = Math.max(.05, Math.min(1.5, act.d * (.4 + du)));

noStroke();
image(S.sky, 0, 0);
const W2 = S.hz0.width;
const scr = (g, px, a) => { const ox = ((px % W2) + W2) % W2; if (a < 100) tint(0, 0, 100, a); image(g, ox - W2, 0); image(g, ox, 0); if (a < 100) noTint(); };

// slow camera drift on two incommensurate rates
const ddx = (Math.sin(K.t * .017) * .7 + Math.sin(K.t * .0391 + 1.4) * .3) * u * .0035 * P.speed;
const ddy = Math.sin(K.t * .0227 + 2.4) * u * .0016;
image(S.pit, ddx, ddy);

// dust hanging in the pit — the guaranteed motion floor, and it reads as depth
scr(S.hz0, -K.t * u * .0105 * P.speed, 100 * Math.min(1, dustAmt));

// ---------------- the pit lake, shimmering ----------------
if (S.lake && !st.pts && !st.line) {
  const lakeC2 = sh(st.lake);
  blendMode(P.style === 'nightwork' ? ADD : BLEND);
  for (let i = 0; i < 22; i++) {
    const a = fr(i * 3 + 901) * Math.PI * 2, rr = Math.sqrt(fr(i * 3 + 902));
    const sm = .5 + .5 * (Math.sin(K.t * (.61 + i * .017) + i) * .55 + Math.sin(K.t * 1.43 + i * 2.1) * .3 + Math.sin(K.t * 2.29 + i) * .15);
    const gain = (.4 + .6 * en) * (.4 + .6 * sm) + A.rms * .4;
    fill(lakeC2[0], lakeC2[1] * .7, Math.min(99, lakeC2[2] + 16 + 20 * gain), 20 + 40 * gain);
    ellipse(S.lake.x + ddx + Math.cos(a) * S.lake.w * .34 * rr, S.lake.y + ddy + Math.sin(a) * S.lake.h * .34 * rr,
            S.lake.w * (.06 + .10 * sm), S.lake.h * .06);
  }
  blendMode(BLEND);
}

// ---------------- a dust plume rising off a working bench and drifting downwind ----------------
const dC2 = sh(st.dust);
const npl = Math.floor(6 + dustAmt * 24);
const bIdx = 1 + Math.floor(fr(31) * Math.max(1, NB - 3));
const src = { x: cx + Math.cos(-2.2 + fr(33) * .8) * ringW(bIdx) * .5, y: ringY(bIdx) + Math.sin(-2.2 + fr(33) * .8) * ringH(bIdx) * .5 };
blendMode(st.pts || st.line ? BLEND : BLEND);
for (let i = 0; i < npl; i++) {
  // each mote runs a continuous linear life and wraps — never re-phases at 8 s
  const life = ((K.t * (.055 + fr(i * 3 + 41) * .05) * P.speed + fr(i * 3 + 42)) % 1);
  const rise = Math.pow(life, .75);
  const px = src.x + ddx + rise * u * (.30 + fr(i * 3 + 43) * .5) + Math.sin(K.t * .6 + i) * u * .01;
  const py = src.y + ddy - rise * u * (.10 + fr(i * 3 + 44) * .16) + Math.sin(K.t * .43 + i * 2) * u * .006;
  const sz = u * (.02 + rise * .11) * (.5 + fr(i * 3 + 45));
  const fade = Math.sin(Math.PI * Math.min(1, life * 1.05));
  fill(dC2[0], dC2[1] * (1 - rise * .3), Math.min(99, dC2[2] + rise * 6), (2 + 10 * dustAmt) * fade * (.4 + .6 * en));
  ellipse(px, py, sz, sz * .62);
}

scr(S.hz1, -K.t * u * .0225 * P.speed - u * .4, 100 * Math.min(1, dustAmt * .8));

// ---------------- light: an overcast sweep, or sodium floods on the night shift ----------------
if (P.style === 'nightwork') {
  for (let i = 0; i < 5; i++) {
    const k2 = 1 + Math.floor(fr(i * 7 + 51) * Math.max(1, NB - 2));
    const a = -Math.PI * (.1 + fr(i * 7 + 52) * .8);
    const fx = cx + ddx + Math.cos(a) * ringW(k2) * .5, fy = ringY(k2) + ddy + Math.sin(a) * ringH(k2) * .5;
    // floods do NOT strobe: a slow lamp-flicker floor, well under any flash threshold
    const fl = .82 + .10 * Math.sin(K.t * (1.7 + i * .43) + i) + .08 * Math.sin(K.t * (.61 + i * .2));
    blendMode(ADD);
    for (let j = 3; j >= 0; j--) {
      fill(sh(st.lip)[0], st.lip[1] * (.8 - j * .12), st.lip[2], (3 + 6 * en) * fl * (1 - j * .18));
      ellipse(fx, fy, u * (.06 + j * .13), u * (.03 + j * .06));
    }
    blendMode(BLEND);
  }
} else if (!st.pts && !st.line) {
  blendMode(ADD);
  const lx = cx + Math.sin(K.t * .0101) * width * .18;
  const swg = (.25 + .75 * en) * act.l * (.75 + .25 * K.swell) + A.lowmid * .18;
  for (let i = 3; i >= 0; i--) {
    fill(sh(st.skyL)[0], st.skyL[1] * .5, st.skyL[2], (3 + 5 * swg) * (1 - i * .17));
    ellipse(lx, rimY + u * (.05 + i * .1), u * (.5 + i * .6), u * (.2 + i * .28));
  }
  blendMode(BLEND);
}

// ---------------- grain + plate edge ----------------
if (st.grain > 6) {
  const ng = Math.floor(st.grain * 6);
  for (let i = 0; i < ng; i++) {
    const gx = ((fr(i * 3 + 701) * width) + Math.sin(K.t * .012 + i) * u * .003 + width) % width;
    const gy = fr(i * 3 + 702) * height;
    fill(hw(st.batter[0] + ho), st.batter[1] * .5, fr(i * 3 + 703) > .5 ? 92 : 5, 3 + fr(i) * 7);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .055);
  stroke(hw(st.batter[0] + ho), st.batter[1], st.pts || st.line ? 4 : 7, 22 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();

if (P.alpha < 1) { fill(hw(st.batter[0] + ho), st.batter[1] * .5, 5, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
